/* Extend the existing units rather than add periods or replace authored text.
   New goals, activities and review prompts also appear in the study notes, so
   the default workbook teaches the added content without needing extra controls.
   The original Assignment section remains the unit's closing section. */
(function () {
  "use strict";
  if (typeof RM_CURRICULUM === "undefined") return;
  RM_FULL_612.forEach(function (extra) {
    var unit = RM_CURRICULUM.filter(function (u) {
      return u.grade === extra.grade && u.period === extra.period;
    })[0];
    if (!unit) throw new Error("Missing RME unit for full details: " + extra.grade + "/" + extra.period);
    if (unit.rmeFullDetails) return;

    var blocks = [
      {k:"rule"},
      {k:"h3", t:"Further Learning Goals"},
      {k:"num", items:extra.objectives.slice()}
    ].concat(extra.study, [
      {k:"h3", t:"Guided Classroom Enquiry"},
      {k:"bul", items:extra.activities.slice()},
      {k:"h3", t:"Check Your Understanding — Extended Review"},
      {k:"num", items:extra.facts.concat(extra.apply).map(function (item) { return item.q; })}
    ]);
    var at = unit.study.length;
    for (var i = 0; i < unit.study.length; i += 1) {
      if (unit.study[i].k === "h3" && /^Assignment/.test(unit.study[i].t)) {
        at = i;
        break;
      }
    }
    if (at > 0 && unit.study[at - 1].k === "rule") at -= 1;
    unit.study.splice.apply(unit.study, [at, 0].concat(blocks));
    ["objectives", "terms", "facts", "tf", "apply", "worked", "activities"].forEach(function (key) {
      unit[key] = (unit[key] || []).concat(extra[key]);
    });
    unit.rmeFullDetails = true;
  });
})();
